sqlite3 -json "/data/arabic_dict.db" "
SELECT 'maqayis' AS type, headword, definitions_text FROM entries WHERE dictionary_id = 151 AND headword_norm IN ('وقد', 'حرق');
SELECT 'ex' AS type, e.headword, ex.text, ex.type FROM examples ex JOIN entries e ON ex.entry_id = e.id WHERE e.headword_norm IN ('وقود', 'الوقود', 'محروقات', 'المحروقات') LIMIT 20;
"

sqlite3 -json "/data/arabic_dict.db" "
SELECT ex.text, ex.type, e.headword FROM examples ex JOIN entries e ON ex.entry_id = e.id WHERE e.headword_norm IN ('وقود', 'الوقود') LIMIT 10;
"
